package local.atmospherevisual;
import me.cryo.zombierool.block.system.*;
import me.cryo.zombierool.gameplay.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.fml.common.Mod;

@Mod("atmospherevisual") public final class FurnitureFollowupTest {
    boolean requested,done;int age,checks;volatile Throwable failure;
    public FurnitureFollowupTest(){MinecraftForge.EVENT_BUS.addListener(this::tick);}
    void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;System.out.println("ATMOSPHERE VISUAL CHECK: "+text);}
    void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> action){var mc=Minecraft.getInstance();mc.getSingleplayerServer().execute(()->{try{action.accept(mc.getSingleplayerServer().getPlayerList().getPlayers().get(0));}catch(Throwable error){failure=error;error.printStackTrace();}});}
    void setup(net.minecraft.server.level.ServerPlayer p){var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);for(var pos:BlockPos.betweenClosed(-8,64,8,8,72,23))l.setBlock(pos,pos.getY()==64?net.minecraft.world.level.block.Blocks.STONE.defaultBlockState():net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);
        for(int i=0;i<32;i++){var pos=new BlockPos(32+i%8*3,65,32+i/8*7);l.setBlock(pos,MapDeviceSystem.ALL_TYPES.get("decor_humvee").get().defaultBlockState(),3);var d=(MapDeviceSystem.Device)l.getBlockEntity(pos);var config=d.config();config.putBoolean("requires_power",false);d.configure(config);d.setActive(true);}
        var first=new BlockPos(32,65,32);var geometry=VehicleDecorPhysics.geometry(l,first);long before=System.nanoTime();MapDeviceSystem.reset(l);long elapsed=(System.nanoTime()-before)/1_000_000;check(l.getBlockState(first).getValue(MapDeviceSystem.DeviceBlock.ACTIVE),"Match reset preserves decorative vehicle activation");check(VehicleDecorPhysics.geometry(l,first)==geometry,"Match reset retains cached vehicle geometry");System.out.println("ATMOSPHERE VISUAL CHECK: Reset with 32 decorative vehicles took "+elapsed+" ms");
        p.getInventory().clearContent();p.setGameMode(net.minecraft.world.level.GameType.ADVENTURE);before=System.nanoTime();WaveManager.startGame(l);check(WaveManager.isGameRunning(),"Match starts with many decorative vehicles");boolean armed=false;for(var stack:p.getInventory().items)armed|=me.cryo.zombierool.core.system.WeaponFacade.isWeapon(stack);check(armed,"Starter weapon is present when match start returns");check(me.cryo.zombierool.gameplay.PointManager.getScore(p)==500,"Start loadout supplies initial points");System.out.println("ATMOSPHERE VISUAL CHECK: Full start with 32 vehicles took "+(System.nanoTime()-before)/1_000_000+" ms");before=System.nanoTime();WaveManager.endGame(l,null);check(!WaveManager.isGameRunning(),"Match ends normally with many decorative vehicles");System.out.println("ATMOSPHERE VISUAL CHECK: Full end with 32 vehicles took "+(System.nanoTime()-before)/1_000_000+" ms");for(int i=0;i<32;i++)l.removeBlock(new BlockPos(32+i%8*3,65,32+i/8*7),false);
        p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);var at=new BlockPos(-3,65,15);var dumpster=(LargeFurnitureBlock)FurnitureSystem.ALL.get("dumpster").get();var state=dumpster.defaultBlockState();l.setBlock(at,state,3);dumpster.setPlacedBy(l,at,state,p,new net.minecraft.world.item.ItemStack(dumpster));l.setBlock(new BlockPos(2,65,15),FurnitureSystem.ALL.get("brazier").get().defaultBlockState(),3);l.setDayTime(6000);p.teleportTo(l,4,68,21,135,20);
    }
    @SuppressWarnings("unchecked") void geist()throws Exception{
        var mc=Minecraft.getInstance();var e=me.cryo.zombierool.init.ZombieroolModEntities.GEIST.get().create(mc.level);e.tickCount=100;
        var ctor=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredConstructor(String.class);ctor.setAccessible(true);var model=(net.minecraft.client.model.EntityModel<net.minecraft.world.entity.LivingEntity>)ctor.newInstance("geist");var bonesField=model.getClass().getDeclaredField("bones");bonesField.setAccessible(true);var bones=(java.util.Map<String,net.minecraft.client.model.geom.ModelPart>)bonesField.get(model);
        var flightCtor=TraversalMotion.Flight.class.getDeclaredConstructors()[0];flightCtor.setAccessible(true);var flight=flightCtor.newInstance(e,new Vec3(0,10,0),new Vec3(0,5,0),Vec3.ZERO,200,0,3);var begin=TraversalMotion.class.getDeclaredMethod("begin",TraversalMotion.Flight.class);begin.setAccessible(true);begin.invoke(null,flight);check(TraversalMotion.active(e),"Geist test uses an actual vertical wall traversal");
        float armMin=100,armMax=-100,legMin=100,legMax=-100;for(int frame=100;frame<=130;frame+=2){e.tickCount=frame;model.setupAnim(e,0,0,frame,0,0);var arm=bones.get("left_arm");var leg=bones.get("right_leg");armMin=Math.min(armMin,arm.xRot);armMax=Math.max(armMax,arm.xRot);legMin=Math.min(legMin,leg.xRot);legMax=Math.max(legMax,leg.xRot);}check(armMax-armMin>.02,"Geist arms animate during vertical descent with zero horizontal walk input");check(legMax-legMin>.02,"Geist legs animate during vertical descent with zero horizontal walk input");TraversalMotion.cancel(e);
    }
    void tick(TickEvent.ClientTickEvent event){if(done||event.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;try{if(failure!=null)throw new AssertionError(failure);if(!requested){requested=true;mc.options.pauseOnLostFocus=false;org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().getWindow());mc.createWorldOpenFlows().loadLevel(mc.screen,"AtmosphereFixture");return;}if(mc.level==null||mc.player==null||mc.isPaused())return;age++;if(age==25)server(this::setup);if(age==40)geist();if(age==55){check(!WaveManager.isGameRunning(),"Client remains stopped after receiving rapid start/end packets");var f=me.cryo.zombierool.client.ClientHUDHandler.class.getDeclaredField("startGameAnimationStartTime");f.setAccessible(true);check(f.getLong(null)==-1,"End packet cancels the pending round announcement");}if(age==55)try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(java.nio.file.Path.of(System.getProperty("atmosphere.output"),"dumpster-brazier.png"));}if(age==65){check(org.lwjgl.opengl.GL11.glGetError()==0,"Large dumpster and animated brazier render without OpenGL errors");done=true;System.out.println("ATMOSPHERE VISUAL PASS: "+checks+" furniture follow-up checks");mc.stop();}}catch(Throwable error){done=true;error.printStackTrace();System.out.println("ATMOSPHERE VISUAL FAIL: "+error);mc.stop();}}
}
